  (1, 1, 1, 'SK-001', '8850000000001', 'เซรั่มวิตามินซี 30ml', 'เซรั่มวิตามินซี 30ml คุณภาพดี จัดส่งไว', 'ผิวกระจ่างใสใน 14 วัน, วิตามินซีเข้มข้น 15%, เนื้อบางเบาไม่เหนียว', 590, 180, 17),
  (2, 1, 1, 'SK-002', '8850000000002', 'กันแดดเนื้อน้ำนม SPF50+', 'กันแดดเนื้อน้ำนม SPF50+ คุณภาพดี จัดส่งไว', 'กันน้ำกันเหงื่อ, ไม่วอก, เหมาะกับผิวมัน', 450, 140, 12),
  (3, 1, 1, 'SK-003', '8850000000003', 'โฟมล้างหน้าอ่อนโยน', 'โฟมล้างหน้าอ่อนโยน คุณภาพดี จัดส่งไว', 'pH 5.5, ไม่มีน้ำหอม, ผิวแพ้ง่ายใช้ได้', 290, 80, 25),
  (4, 1, 1, 'SK-004', '8850000000004', 'มาส์กหน้าคอลลาเจน (10 แผ่น)', 'มาส์กหน้าคอลลาเจน (10 แผ่น) คุณภาพดี จัดส่งไว', 'ผิวชุ่มชื้นทันที, คอลลาเจนจากปลาทะเล', 350, 95, 20),
  (5, 1, 2, 'SP-001', '8850000000005', 'คอลลาเจนเปปไทด์ชงดื่ม', 'คอลลาเจนเปปไทด์ชงดื่ม คุณภาพดี จัดส่งไว', 'ดูดซึมไว, ไม่คาว, ชงง่ายละลายไว', 890, 320, 24),
  (6, 1, 2, 'SP-002', '8850000000006', 'วิตามินรวม 60 แคปซูล', 'วิตามินรวม 60 แคปซูล คุณภาพดี จัดส่งไว', 'วิตามิน 13 ชนิด, ทานวันละ 1 เม็ด', 690, 210, 25),
  (7, 1, 2, 'SP-003', '8850000000007', 'โปรตีนพืชรสช็อกโกแลต', 'โปรตีนพืชรสช็อกโกแลต คุณภาพดี จัดส่งไว', 'โปรตีน 25g ต่อช้อน, ไม่มีแลคโตส', 1290, 520, 25),
  (8, 1, 3, 'GD-001', '8850000000008', 'หูฟังไร้สาย ANC', 'หูฟังไร้สาย ANC คุณภาพดี จัดส่งไว', 'ตัดเสียงรบกวน, แบตอึด 30 ชม., กันน้ำ IPX5', 1590, 780, 25),
  (9, 1, 3, 'GD-002', '8850000000009', 'พาวเวอร์แบงก์ 20000mAh', 'พาวเวอร์แบงก์ 20000mAh คุณภาพดี จัดส่งไว', 'ชาร์จเร็ว PD 22.5W, พกขึ้นเครื่องได้', 790, 380, 24),
  (10, 1, 3, 'GD-003', '8850000000010', 'ขาตั้งมือถือไลฟ์สด + ไฟ LED', 'ขาตั้งมือถือไลฟ์สด + ไฟ LED คุณภาพดี จัดส่งไว', 'ปรับแสง 3 โหมด, ยืดได้ 1.6 เมตร', 490, 190, 11),
  (11, 1, 3, 'GD-004', '8850000000011', 'สายชาร์จ USB-C ถักไนลอน', 'สายชาร์จ USB-C ถักไนลอน คุณภาพดี จัดส่งไว', 'ทนทาน งอได้ 30,000 ครั้ง', 199, 45, 21),
  (12, 1, 4, 'HM-001', '8850000000012', 'ไม้ถูพื้นสเปรย์', 'ไม้ถูพื้นสเปรย์ คุณภาพดี จัดส่งไว', 'หัวสเปรย์ในตัว, ผ้าไมโครไฟเบอร์ซักได้', 390, 150, 25),
  (13, 1, 4, 'HM-002', '8850000000013', 'กล่องเก็บของซ้อนได้ (ชุด 3)', 'กล่องเก็บของซ้อนได้ (ชุด 3) คุณภาพดี จัดส่งไว', 'พลาสติก BPA free, ซ้อนได้ประหยัดพื้นที่', 459, 170, 24),
  (14, 1, 4, 'HM-003', '8850000000014', 'เครื่องพ่นอโรม่า', 'เครื่องพ่นอโรม่า คุณภาพดี จัดส่งไว', 'ตั้งเวลาได้, ไฟ 7 สี, เงียบ', 690, 260, 14),
  (15, 1, 4, 'HM-004', '8850000000015', 'ถุงขยะย่อยสลายได้ (100 ใบ)', 'ถุงขยะย่อยสลายได้ (100 ใบ) คุณภาพดี จัดส่งไว', 'ย่อยสลายใน 180 วัน', 149, 55, 12),
  (16, 1, 5, 'FS-001', '8850000000016', 'เสื้อโอเวอร์ไซซ์ผ้าคอตตอน', 'เสื้อโอเวอร์ไซซ์ผ้าคอตตอน คุณภาพดี จัดส่งไว', 'ผ้าคอตตอน 100%, ไม่ย้วย', 390, 120, 18),
  (17, 1, 5, 'FS-002', '8850000000017', 'กระเป๋าผ้าแคนวาส', 'กระเป๋าผ้าแคนวาส คุณภาพดี จัดส่งไว', 'ใส่แล็ปท็อป 14 นิ้วได้', 290, 85, 21),
  (18, 1, 5, 'FS-003', '8850000000018', 'หมวกบักเก็ตกันแดด', 'หมวกบักเก็ตกันแดด คุณภาพดี จัดส่งไว', 'กัน UV, พับเก็บได้', 250, 70, 25),
  (19, 1, 5, 'FS-004', '8850000000019', 'ถุงเท้าข้อสั้น (แพ็ก 5)', 'ถุงเท้าข้อสั้น (แพ็ก 5) คุณภาพดี จัดส่งไว', 'ระบายอากาศดี', 159, 40, 11),
  (20, 1, 5, 'FS-005', '8850000000020', 'แว่นกันแดดโพลาไรซ์', 'แว่นกันแดดโพลาไรซ์ คุณภาพดี จัดส่งไว', 'ตัดแสงสะท้อน, UV400', 590, 160, 23);
